int register_mii_bus(struct mii_bus *bus, struct module *owner)
{
    int ret;
    int phy_id;
    struct phy_device *phy_dev;

    if (!bus || !bus->name || !bus->read || !bus->write)
        return -EINVAL;

    ret = device_register(&bus->dev);
    if (ret < 0)
        return ret;

    mutex_init(&bus->bus_mutex);
    if (bus->reset_gpio) {
        gpio_set_value(bus->reset_gpio, 0);
        msleep(100);
        gpio_set_value(bus->reset_gpio, 1);
    }

    for (phy_id = 0; phy_id < PHY_MAX_ADDR; phy_id++) {
        phy_dev = phy_device_create(bus, phy_id);
        if (!phy_dev) {
            ret = -ENOMEM;
            goto error_cleanup;
        }

        if (IS_ERR(phy_dev)) {
            ret = PTR_ERR(phy_dev);
            goto error_cleanup;
        }

        ret = phy_device_register(phy_dev);
        if (ret < 0) {
            phy_device_free(phy_dev);
            goto error_cleanup;
        }
    }

    bus->state = MII_BUS_READY;
    dev_info(&bus->dev, "MII bus probed successfully\n");
    return 0;

error_cleanup:
    for (phy_id = 0; phy_id < PHY_MAX_ADDR; phy_id++) {
        phy_dev = bus->phy_dev[phy_id];
        if (phy_dev && !IS_ERR(phy_dev)) {
            phy_device_unregister(phy_dev);
            phy_device_free(phy_dev);
        }
    }
    device_unregister(&bus->dev);
    return ret;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner) {
    int ret;
    int i;

    if (!bus || !bus->name || !bus->read || !bus->write || !bus->phy_mask) {
        return -EINVAL;
    }

    bus->owner = owner;
    mutex_init(&bus->bus_mutex);

    ret = device_register(&bus->dev);
    if (ret) {
        return ret;
    }

    for (i = 0; i < 32; i++) {
        if ((1 << i) & bus->phy_mask) {
            struct phy_device *phydev;

            phydev = phy_device_create(bus, i, 0);
            if (!phydev) {
                while (i > 0) {
                    i--;
                    phy_device_free(phydev);
                }
                device_unregister(&bus->dev);
                return -ENOMEM;
            }

            if (!phydev->attached_dev) {
                phydev->attached_dev = phy_get_drvdata(phydev);
                if (!phydev->attached_dev) {
                    phy_device_free(phydev);
                    device_unregister(&bus->dev);
                    return -ENODEV;
                }
            }

            phydev->state = PHY_READY;
            phy_link_up(phydev);
        }
    }

    dev_info(&bus->dev, "Probing MII bus %s\n", bus->name);
    bus->state = MII_BUS_READY;

    return 0;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner) {
    int ret;
    int i;

    if (!bus) {
        return -EINVAL;
    }

    bus->owner = owner;

    ret = device_register(&bus->dev);
    if (ret < 0) {
        return ret;
    }

    mutex_init(&bus->lock);

    if (bus->reset) {
        ret = bus->reset(bus);
        if (ret < 0) {
            goto out_unregister_dev;
        }
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        struct phy_device *phydev = get_phy_device(bus, i, false);
        if (IS_ERR(phydev)) {
            ret = PTR_ERR(phydev);
            goto out_unregister_dev;
        }

        if (!phydev) {
            phydev = phy_device_create(bus, i);
            if (IS_ERR(phydev)) {
                ret = PTR_ERR(phydev);
                goto out_unregister_dev;
            }
        }

        phy_register(phydev);
    }

    bus->state = MII_BUS_READY;
    dev_info(&bus->dev, "Probed MII bus with %d PHY devices\n", i);

    return 0;

out_unregister_dev:
    for (i = 0; i < PHY_MAX_ADDR; i++) {
        struct phy_device *phydev = bus->phydevs[i];
        if (phydev) {
            phy_unregister(phydev);
            phy_device_free(phydev);
        }
    }
    device_unregister(&bus->dev);
    return ret;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner) {
    int ret;
    int i;

    if (!bus || !bus->name || !bus->read || !bus->write)
        return -EINVAL;

    ret = device_register(&bus->dev);
    if (ret < 0)
        return ret;

    mutex_init(&bus->bus_mutex);

    for (i = 0; i < MAX_MII_DEVICES; i++) {
        struct phy_device *phydev = get_phy_device(bus, i);
        if (!phydev)
            continue;

        if (!phydev->is_present) {
            ret = phy_device_init(phydev);
            if (ret < 0) {
                phy_device_free(phydev);
                while (--i >= 0) {
                    struct phy_device *old = get_phy_device(bus, i);
                    if (old && old->is_present)
                        phy_device_free(old);
                }
                device_unregister(&bus->dev);
                return ret;
            }
        }
        phydev->is_registered = true;
    }

    bus->state = MII_BUS_REGISTERED;
    pr_info("MII bus registered with %d PHY devices\n", bus->phy_count);

    return 0;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner)
{
    int ret;
    int i;

    if (!bus || !bus->name || !bus->read || !bus->write) {
        return -EINVAL;
    }

    mutex_init(&bus->bus_mutex);

    ret = device_register(&bus->dev);
    if (ret) {
        return ret;
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        struct phy_device *phydev;

        phydev = phy_device_create(bus, i, 0);
        if (!phydev) {
            while (--i >= 0) {
                phy_device_free(bus->phydev[i]);
            }
            device_unregister(&bus->dev);
            return -ENOMEM;
        }

        bus->phydev[i] = phydev;
    }

    if (bus->reset) {
        bus->reset(bus);
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        if (bus->phydev[i]) {
            phy_device_start(bus->phydev[i]);
        }
    }

    dev_info(&bus->dev, "Probed MII bus %s\n", bus->name);
    return 0;
}
